'use strict';
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const OUT = process.env.OB64_ITER || 'C:/Users/Joe/AppData/Local/Temp/ob64_iter';
const ROOT = 'C:/Users/Joe/Projects/OgreBattlel64/OB64 Decomp';
const CC = 'C:/Users/Joe/.codex/ob64-phase6-kmc-20260801/clean-d/toolchain/kmc-gcc-2.7.2/cc1.exe';
const AS = ROOT + '/.toolchains/gnu-binutils-2.6-mips-kmc-elf-msys2/bin/mips-kmc-elf-as.exe';
const FLAGS = ['-quiet', '-O2', '-meb', '-mips3', '-mgp32', '-mfp32', '-G', '0', '-fno-PIC', '-mno-abicalls', '-fno-builtin', '-funsigned-char'];
const ASFLAGS = ['-G', '0', '-mips3', '-mabi=32', '-force-n64align', '-EB'];

function build(name, sourceText) {
  const cFile = path.join(OUT, name + '.c');
  fs.writeFileSync(cFile, sourceText);
  const sFile = path.join(OUT, name + '.s');
  execFileSync(CC, [...FLAGS, '-o', sFile, cFile], { cwd: ROOT, stdio: 'pipe' });
  let asmText = fs.readFileSync(sFile, 'utf8');
  asmText = asmText.replace(/^[ \t]*\.text[ \t]*$/m, '.section .ob64.r0236,"ax",@progbits');
  const secFile = path.join(OUT, name + '.sec.s');
  fs.writeFileSync(secFile, asmText);
  const oFile = path.join(OUT, name + '.o');
  execFileSync(AS, [...ASFLAGS, '-o', oFile, secFile], { cwd: ROOT, stdio: 'pipe' });
  return oFile;
}

module.exports = { build, OUT };

'use strict';
const { execFileSync } = require('child_process');
const { build } = require('./iter_lib');

const base = `typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned int u32;
typedef int s32;

typedef struct Func000135A0State {
    u8 pad_00[0x0C];
    s32 field_0C;
    u8 pad_10[0x04];
    s32 field_14;
    u8 pad_18[0x20];
    u8 *field_38;
    u8 pad_3C[0x66];
    u16 field_A2;
    u8 pad_A4[0x18];
    u8 field_BC;
} Func000135A0State;

void func_000135a0(Func000135A0State *arg0)
{
    s32 wait_one;
    u16 wait_count;
    s32 elapsed;
    u8 *cursor;
    u8 *extra_cursor;
    u8 opcode_byte;
    u16 high_bits;

    wait_one = 1;
    while (1) {
        elapsed = arg0->field_14 + 0x100;
        wait_count = arg0->field_A2 - 1;
        arg0->field_14 = elapsed;
        arg0->field_A2 = wait_count;
        if ((u16)wait_count == 0) {
            cursor = arg0->field_38;
            arg0->field_38 = cursor + 1;
            opcode_byte = *cursor;
            if ((u32)opcode_byte >= 0x80) {
                arg0->field_BC = opcode_byte & 0x7F;
                cursor = arg0->field_38;
                arg0->field_38 = cursor + 1;
                opcode_byte = *cursor;
                if ((u32)opcode_byte >= 0x80) {
                    high_bits = (opcode_byte & 0x7F) << 8;
                    arg0->field_A2 = high_bits;
                    extra_cursor = arg0->field_38;
                    arg0->field_38 = extra_cursor + 1;
                    opcode_byte = *extra_cursor;
                    arg0->field_A2 = opcode_byte + (high_bits + 2);
                } else {
                    arg0->field_A2 = opcode_byte + 2;
                }
            } else {
                arg0->field_BC = opcode_byte;
                arg0->field_A2 = wait_one;
            }
        }
        if (arg0->field_14 - arg0->field_0C >= 0) {
            return;
        }
    }
}
`;

const variants = {
  v24: base,
  p1: base.replace('    u8 *cursor;\n    u8 *extra_cursor;', '    u8 *extra_cursor;\n    u8 *cursor;'),
  p2: base.replace('    u16 high_bits;', '    s32 high_bits;'),
  p3: base.replace('    u8 opcode_byte;', '    u32 opcode_byte;'),
  p4: base
    .replace('    s32 wait_one;\n    u16 wait_count;\n    s32 elapsed;\n    u8 *cursor;\n    u8 *extra_cursor;\n    u8 opcode_byte;\n    u16 high_bits;',
             '    u8 *cursor;\n    u8 *extra_cursor;\n    u8 opcode_byte;\n    u16 high_bits;\n    s32 wait_one;\n    u16 wait_count;\n    s32 elapsed;'),
};

for (const [name, text] of Object.entries(variants)) {
  try {
    const obj = build(name, text);
    const out = execFileSync(process.execPath, ['build/iter_compare.js', obj], { cwd: process.cwd(), encoding: 'utf8' });
    const first = out.split(/\r?\n/).slice(0, 3).join(' | ');
    console.log(name.padEnd(5), first);
  } catch (e) {
    console.log(name.padEnd(5), 'FAILED', e.message.split('\n')[0]);
  }
}

