'use strict';
const path = require('path');
const fs = require('fs');
const { parseElfFile, elfSectionBytes } = require(path.join(__dirname, '..', 'tools', 'lib', 'phase7_conventional'));

const objectFile = process.argv[2];
const elf = parseElfFile(objectFile);
const text = elf.sections.find((s) => s.name === '.text')
  || elf.sections.find((s) => /^\.ob64\./.test(s.name) && s.size > 0);
const mine = Buffer.from(elfSectionBytes(elf, text));
const rom = fs.readFileSync(path.join(__dirname, 'baserom.us_rev0.z64'));
const start = 0x135A0;
const end = 0x13664;
const expected = rom.subarray(start, end);
console.log(`compiled words: ${mine.length / 4}  expected words: ${expected.length / 4}`);
let diffs = 0;
const max = Math.max(mine.length, expected.length);
for (let i = 0; i < max; i += 4) {
  const m = mine.subarray(i, i + 4);
  const e = expected.subarray(i, i + 4);
  if (!m.equals(e)) {
    diffs += 1;
    console.log(`word ${(i / 4).toString().padStart(2)} (0x${(start + i).toString(16).padStart(6, '0')}): mine ${m.toString('hex') || '------'}  want ${e.toString('hex') || '------'}`);
  }
}
if (diffs === 0 && mine.length === expected.length) {
  console.log('EXACT MATCH');
} else {
  console.log(`${diffs} differing words`);
}

